// The online shop the evaluation runs on (generated by generate-data.mjs).
// The CSV files are registered in DuckDB's virtual file system, like files a
// user drops into the terminal; all but the web events are loaded as tables.

import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const dataDir = resolve(dirname(fileURLToPath(import.meta.url)), 'data');

export const DATA_FILES = ['customers.csv', 'products.csv', 'orders.csv', 'order_items.csv', 'refunds.csv', 'web_events.csv'];

/** File name and text of every data file. */
export function readDataFiles() {
  return DATA_FILES.map((name) => ({ name, text: readFileSync(resolve(dataDir, name), 'utf8') }));
}

/** The tables created from the data files. */
export const TABLES = ['customers', 'products', 'orders', 'order_items', 'refunds'];

/** Restores the tables before each task and removes what earlier tasks created. */
export const SETUP_SQL = [
  ...TABLES.map(
    (table) => `CREATE OR REPLACE TABLE ${table} AS SELECT * FROM read_csv('${table}.csv')`
  ),
  'DROP TABLE IF EXISTS monthly_revenue',
];

/** Files tasks may write, removed before each task. */
export const OUTPUT_FILES = ['german_customers.csv'];
